const inicio = Date.now();
const fonte = $json.fonte;
const janela = $json.janela;
const modo = $json.modo;
const versaoApi = 'v26';

const administradora = String(fonte.managerExternalId || fonte.externalId).replace(/\D/g, '');
const cliente = String(fonte.externalId).replace(/\D/g, '');
const limite = modo === 'amostra' ? ' LIMIT 500' : '';

const query = `SELECT campaign.id, campaign.name, segments.date, metrics.cost_micros, metrics.impressions, metrics.clicks, metrics.conversions, metrics.conversions_value FROM campaign WHERE segments.date BETWEEN '${janela.start}' AND '${janela.end}'${limite}`;

function devolver(linhas, falhas, requests, bytes) {
  return [{
    json: {
      linhas,
      volumetria: { linhas: linhas.length, bytes, requests, duracaoMs: Date.now() - inicio },
      falhas,
      requests,
      versaoApi,
    },
  }];
}

let resposta;
try {
  resposta = await this.helpers.httpRequestWithAuthentication.call(this, 'googleOAuth2Api', {
    method: 'POST',
    url: `https://googleads.googleapis.com/${versaoApi}/customers/${cliente}/googleAds:searchStream`,
    headers: { 'login-customer-id': administradora, 'Content-Type': 'application/json' },
    body: { query },
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  });
} catch (erro) {
  return devolver([], [{ causa: 'api_recusou', detalhe: `falha de rede: ${erro.message}` }], 1, 0);
}

if (resposta.statusCode === 401 || resposta.statusCode === 403) {
  const detalhe = resposta.body?.error?.message || `HTTP ${resposta.statusCode}`;
  return devolver([], [{ causa: 'reauth_pending', detalhe }], 1, 0);
}

if (resposta.statusCode < 200 || resposta.statusCode >= 300) {
  const detalhe = resposta.body?.error?.message || `HTTP ${resposta.statusCode}`;
  return devolver([], [{ causa: 'api_recusou', detalhe }], 1, 0);
}

const lotes = Array.isArray(resposta.body) ? resposta.body : [resposta.body];
const linhasBrutas = lotes.flatMap((lote) => lote.results || []);
const bytes = JSON.stringify(resposta.body).length;

const linhas = linhasBrutas.map((linha) => ({
  externalCampaignId: String(linha.campaign?.id ?? ''),
  campaignName: linha.campaign?.name ?? null,
  metricDate: linha.segments?.date ?? null,
  spend: Number(linha.metrics?.costMicros ?? 0) / 1_000_000,
  impressions: Number(linha.metrics?.impressions ?? 0),
  clicks: Number(linha.metrics?.clicks ?? 0),
  conversions: Number(linha.metrics?.conversions ?? 0),
  revenue: Number(linha.metrics?.conversionsValue ?? 0),
  currency: fonte.currency || 'BRL',
}));

if (linhas.length === 0) {
  return devolver([], [{ causa: 'sem_dados_no_periodo', detalhe: null }], 1, bytes);
}

return devolver(linhas, [], 1, bytes);
